// [FIX #11] Дедупликация + санитизация входных данных
const message = $input.first().json.message;

if (!message) {
  return [{ json: { error: true, errorMessage: 'No message found' } }];
}

const chatId = message.chat.id;
const text = (message.text || '').trim();

// [FIX] Санитизация username - убираем опасные символы
let username = message.from.username || message.from.first_name || 'User';
username = username.replace(/[<>"'`;\\]/g, '').substring(0, 64);

// Определяем тип сообщения
let messageType = 'text';
let command = null;

if (text.startsWith('/')) {
  messageType = 'command';
  command = text.split(' ')[0].toLowerCase().replace(/[^a-z\/]/g, '');
}

// [FIX #11] ID для дедупликации
const updateId = $input.first().json.update_id;

return [{
  json: {
    chatId,
    text,
    username,
    messageType,
    command,
    updateId,
    timestamp: new Date().toISOString()
  }
}];

// Извлекаем данные из callback_query с санитизацией
const callback = $input.first().json.callback_query;

if (!callback) {
  return [{ json: { error: true, errorMessage: 'No callback found' } }];
}

const chatId = callback.message.chat.id;
// [FIX] Валидация callbackData - только разрешённые значения
const allowedCallbacks = ['ai_advice'];
const callbackData = allowedCallbacks.includes(callback.data) ? callback.data : 'unknown';
const messageId = callback.message.message_id;

let username = callback.from.username || callback.from.first_name || 'User';
username = username.replace(/[<>"'`;\\]/g, '').substring(0, 64);

return [{
  json: {
    chatId,
    callbackData,
    messageId,
    username,
    messageType: 'callback',
    timestamp: new Date().toISOString()
  }
}];

// [FIX #7, #10] Определяем состояние с fallback + убраны хрупкие ссылки
const prevNode = $input.first().json;
const parseMessage = $('Parse Message').first().json;

const chatId = parseMessage.chatId;
const text = parseMessage.text;
const command = parseMessage.command;
const username = parseMessage.username;

// [FIX #7] Fallback если Redis недоступен
let state = 'base';
try {
  state = prevNode.value || 'base';
} catch (e) {
  state = 'base';
}

// Определяем действие
let action = 'unknown';

if (command === '/start') {
  action = 'start';
} else if (command === '/status') {
  action = 'status';
} else if (command === '/report') {
  action = 'report';
} else if (command === '/help') {
  action = 'help';
} else if (state === 'set_limit') {
  action = 'save_budget';
} else if (state === 'base' && text.length > 0) {
  action = 'parse_expense';
}

return [{
  json: {
    chatId,
    text,
    command,
    username,
    state,
    action,
    timestamp: new Date().toISOString()
  }
}];

// [FIX #12] Улучшенная валидация бюджета
const text = $json.text;
const chatId = $json.chatId;

// Убираем пробелы и конвертируем запятые
const cleanText = text.replace(/\s/g, '').replace(',', '.');
const budgetLimit = parseFloat(cleanText);

// [FIX #12] Расширенная валидация
if (isNaN(budgetLimit)) {
  return [{
    json: {
      chatId,
      valid: false,
      error: 'Пожалуйста, введите число. Например: 50000'
    }
  }];
}

if (budgetLimit <= 0) {
  return [{
    json: {
      chatId,
      valid: false,
      error: 'Бюджет должен быть больше 0'
    }
  }];
}

if (budgetLimit > 100000000) {
  return [{
    json: {
      chatId,
      valid: false,
      error: 'Слишком большое значение. Максимум: 100,000,000 ₽'
    }
  }];
}

return [{
  json: {
    chatId,
    valid: true,
    budgetLimit: Math.round(budgetLimit * 100) / 100
  }
}];

