// [FIX #5, #11] Улучшенный парсер с fallback на regex + обработка ошибок AI
const aiInput = $input.first()?.json;
const aiResponse = aiInput?.text || '';
const chatId = $('Determine Action').first().json.chatId;
const originalText = $('Determine Action').first().json.text;

let parsed = null;

// [FIX #11] Проверка что AI вообще ответил
if (!aiResponse) {
  console.log('AI did not respond, using regex fallback');
} else {
  // Попытка 1: Парсим JSON от AI
  try {
    let cleanResponse = aiResponse;
    if (cleanResponse.includes('```json')) {
      cleanResponse = cleanResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '');
    }
    if (cleanResponse.includes('```')) {
      cleanResponse = cleanResponse.replace(/```\n?/g, '');
    }
    parsed = JSON.parse(cleanResponse.trim());
  } catch (e) {
    console.log('AI parse failed, trying regex fallback:', e.message);
  }
}

// [FIX #5, #10] Regex fallback если AI не справился
if (!parsed || (!parsed.category?.trim() && !parsed.error)) {
  const regexMatch = originalText.match(/^([а-яА-ЯёЁa-zA-Z]+)\s+(\d+(?:[.,]\d+)?)$/u);

  if (regexMatch) {
    const category = regexMatch[1].charAt(0).toUpperCase() + regexMatch[1].slice(1).toLowerCase();
    const amount = parseFloat(regexMatch[2].replace(',', '.'));

    if (amount > 0 && amount < 10000000) {
      parsed = {
        category: category.substring(0, 50),
        amount: amount,
        error: false,
        error_message: null
      };
    }
  }
}

// Финальная проверка
if (!parsed) {
  parsed = {
    error: true,
    error_message: 'Не удалось распознать трату. Формат: Категория Сумма (например: Продукты 1500)'
  };
}

// [FIX] Валидация amount
if (parsed.amount && (parsed.amount <= 0 || parsed.amount > 10000000)) {
  parsed = {
    error: true,
    error_message: 'Сумма должна быть от 1 до 10,000,000 ₽'
  };
}

return [{
  json: {
    chatId,
    ...parsed
  }
}];

