// Форматируем статус
const stats = $input.first().json;
const chatId = $('Determine Action').first().json.chatId;

const totalSpent = parseFloat(stats.total_spent || 0);
const budgetLimit = parseFloat(stats.budget_limit || 0);
const remaining = parseFloat(stats.remaining || 0);
const percentUsed = parseFloat(stats.percent_used || 0);
const txCount = parseInt(stats.transaction_count || 0);

let statusEmoji = '✅';
let progressBar = '';

// Создаём прогресс-бар
const filled = Math.min(Math.round(percentUsed / 10), 10);
const empty = 10 - filled;
progressBar = '█'.repeat(filled) + '░'.repeat(empty);

if (percentUsed >= 100) {
  statusEmoji = '🚨 БЮДЖЕТ ПРЕВЫШЕН!';
} else if (percentUsed >= 80) {
  statusEmoji = '⚠️ Внимание!';
} else if (percentUsed >= 50) {
  statusEmoji = '📊 Всё под контролем';
} else {
  statusEmoji = '✅ Отлично!';
}

const message = `${statusEmoji}

💰 *Статус бюджета на ${new Date().toLocaleDateString('ru-RU')}*

${progressBar} ${percentUsed}%

📈 Лимит: ${budgetLimit.toLocaleString('ru-RU')} ₽
💸 Потрачено: ${totalSpent.toLocaleString('ru-RU')} ₽
💵 Осталось: ${remaining.toLocaleString('ru-RU')} ₽
📝 Транзакций: ${txCount}

💡 /report - подробный отчёт`;

return [{
  json: { chatId, message }
}];

