if (categories && categories.length > 0 && categories[0].category) {
  categoriesText = categories
    .map((c, i) => {
      const emoji = ['🥇', '🥈', '🥉', '📍', '📍'][i] || '📍';
      return `${emoji} ${c.category}: ${parseFloat(c.total_amount).toLocaleString('ru-RU')} ₽ (${c.percentage}%)`;
    })
    .join('\n');
} else {
  categoriesText = '_Нет расходов за этот месяц_';
}

// Прогресс-бар
const filled = Math.min(Math.round(percentUsed / 10), 10);
const empty = 10 - filled;
const progressBar = '█'.repeat(filled) + '░'.repeat(empty);

const monthName = new Date().toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' });

const message = `📊 *ОТЧЁТ ЗА ${monthName.toUpperCase()}*

${progressBar} ${percentUsed}%

💰 *Общая статистика:*
• Бюджет: ${budgetLimit.toLocaleString('ru-RU')} ₽
• Потрачено: ${totalSpent.toLocaleString('ru-RU')} ₽
• Осталось: ${remaining.toLocaleString('ru-RU')} ₽

📁 *Расходы по категориям:*
${categoriesText}

💡 Нажмите кнопку ниже для AI-анализа ваших трат`;

